package com.veronic.guardbox.util

import android.util.Log
import com.veronic.guardbox.data.api.ActiveAlertData

/**
 * Isolated, secure helper for resolving remote evidence snapshot URLs
 * on authenticated Android clients without embedding Supabase secret keys in the app.
 * Utilizes time-limited signed URLs generated by the trusted backend.
 */
object RemoteEvidenceHelper {
    private const val TAG = "RemoteEvidenceHelper"

    /**
     * Resolves the remote snapshot viewing URL from the alert metadata.
     * Structured diagnostic logging ensures visibility without leaking credentials.
     */
    fun resolveRemoteUrl(alert: ActiveAlertData?): String? {
        if (alert == null) return null
        val id = alert.effectiveAlertId ?: "unknown"
        val remoteUrl = alert.effectiveRemoteUrl
        val remoteRef = alert.effectiveRemoteReference
        val provider = alert.effectiveRemoteProvider

        Log.i(
            TAG,
            "[TRINETRA REMOTE EVIDENCE]\n" +
            "alertId=$id\n" +
            "remoteProvider=$provider\n" +
            "remoteReference=${remoteRef ?: "None"}\n" +
            "hasSignedUrl=${!remoteUrl.isNullOrBlank()}"
        )

        return remoteUrl?.takeIf { it.isNotBlank() }
    }
}
